import { test } from 'node:test';
import assert from 'node:assert/strict';
import { parseCsv, csvToMarkdownTable } from './convert.mjs';

test('parseCsv splits basic rows', () => {
  assert.deepEqual(parseCsv('a,b,c\n1,2,3'), [
    ['a', 'b', 'c'],
    ['1', '2', '3'],
  ]);
});

test('parseCsv handles quoted fields with commas and escaped quotes', () => {
  assert.deepEqual(parseCsv('name,quote\n"Doe, Jane","She said ""hi"""'), [
    ['name', 'quote'],
    ['Doe, Jane', 'She said "hi"'],
  ]);
});

test('csvToMarkdownTable renders a GitHub-flavored markdown table', () => {
  const csv = 'name,age\nAda,36\nGrace,85';
  const table = csvToMarkdownTable(csv);
  assert.equal(
    table,
    ['| name | age |', '| --- | --- |', '| Ada | 36 |', '| Grace | 85 |'].join('\n')
  );
});

test('csvToMarkdownTable escapes pipe characters in cells', () => {
  const csv = 'a,b\n1|2,3';
  const table = csvToMarkdownTable(csv);
  assert.equal(table, ['| a | b |', '| --- | --- |', '| 1\\|2 | 3 |'].join('\n'));
});

test('csvToMarkdownTable returns an empty string for empty input', () => {
  assert.equal(csvToMarkdownTable(''), '');
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { csvToMarkdownTable, parseCsv } from './convert.mjs';

test('converts a simple csv into a markdown table', () => {
  const csv = 'name,age\nAda,36\nGrace,85\n';
  const table = csvToMarkdownTable(csv);
  assert.equal(
    table,
    ['| name | age |', '| --- | --- |', '| Ada | 36 |', '| Grace | 85 |'].join('\n')
  );
});

test('handles quoted fields containing commas and doubled quotes', () => {
  const csv = 'city,note\n"Springfield, IL","Home of the ""Simpsons"""\n';
  const rows = parseCsv(csv);
  assert.deepEqual(rows, [
    ['city', 'note'],
    ['Springfield, IL', 'Home of the "Simpsons"'],
  ]);
});

test('escapes pipe and backslash characters so the table does not break', () => {
  const csv = 'a,b\n1|2,c:\\d\n';
  const table = csvToMarkdownTable(csv);
  const lines = table.split('\n');
  assert.equal(lines[2], '| 1\\|2 | c:\\\\d |');
});

test('pads ragged rows to match the header width', () => {
  const csv = 'a,b,c\n1,2\n3,4,5,6\n';
  const table = csvToMarkdownTable(csv);
  const lines = table.split('\n');
  assert.equal(lines[2], '| 1 | 2 |  |');
  assert.equal(lines[3], '| 3 | 4 | 5 |');
});

test('returns an empty string for empty input', () => {
  assert.equal(csvToMarkdownTable(''), '');
});
